import React from "react";

interface ActionBarProps {
  onReadSelection: () => void;
  onReadDocument: () => void;
  onOpenDocTools: () => void;
  onOpenTemplates: () => void;
  onReplace: () => void;
  onClear: () => void;
  onCheckSpelling: () => void;
  onCheckGrammar: () => void;
  isLoading: boolean;
  hasText: boolean;
  spellingCount?: number;
  grammarCount?: number;
}

export const ActionBar: React.FC<ActionBarProps> = ({
  onReadSelection,
  onReadDocument,
  onOpenDocTools,
  onOpenTemplates,
  onReplace,
  onClear,
  onCheckSpelling,
  onCheckGrammar,
  isLoading,
  hasText,
  spellingCount,
  grammarCount,
}) => {
  return (
    <div className="action-bar">
      <div className="action-row">
        <button
          className="action-btn action-btn-primary"
          onClick={onReadSelection}
          disabled={isLoading}
          title="Word में चयनित text पढ़ें"
        >
          <span className="action-btn-icon">📋</span>
          <span className="action-btn-label">चयन पढ़ें</span>
        </button>
        <button
          className="action-btn action-btn-secondary"
          onClick={onReadDocument}
          disabled={isLoading}
          title="पूरा दस्तावेज़ पढ़ें"
        >
          <span className="action-btn-icon">📄</span>
          <span className="action-btn-label">पूरा दस्तावेज़</span>
        </button>
        <button
          className="action-btn action-btn-template"
          onClick={onOpenTemplates}
          disabled={isLoading}
          title="सरकारी पत्र एवं आवेदन प्रारूप तैयार करें"
        >
          <span className="action-btn-icon">📝</span>
          <span className="action-btn-label">पत्र प्रारूप</span>
        </button>
        <button
          className="action-btn action-btn-tools"
          onClick={onOpenDocTools}
          disabled={isLoading}
          title="दस्तावेज़ स्कैन एवं विशेष उपकरण"
        >
          <span className="action-btn-icon">📑</span>
          <span className="action-btn-label">टूल्स</span>
        </button>
      </div>
      <div className="action-row">
        <button
          className="action-btn action-btn-spell"
          onClick={onCheckSpelling}
          disabled={isLoading || !hasText}
          title="हिन्दी वर्तनी और गलतियों की जाँच करें"
        >
          <span className="action-btn-icon">🔍</span>
          <span className="action-btn-label">
            वर्तनी {spellingCount !== undefined && spellingCount > 0 ? `(${spellingCount})` : ""}
          </span>
        </button>
        <button
          className="action-btn action-btn-grammar"
          onClick={onCheckGrammar}
          disabled={isLoading || !hasText}
          title="व्याकरण और सरकारी प्रशासनिक शैली की जाँच करें"
        >
          <span className="action-btn-icon">✍️</span>
          <span className="action-btn-label">
            व्याकरण {grammarCount !== undefined && grammarCount > 0 ? `(${grammarCount})` : ""}
          </span>
        </button>
        <button
          className="action-btn action-btn-success"
          onClick={onReplace}
          disabled={isLoading || !hasText}
          title="चयनित text को बदलें"
        >
          <span className="action-btn-icon">✏️</span>
          <span className="action-btn-label">बदलें</span>
        </button>
        <button
          className="action-btn action-btn-neutral"
          onClick={onClear}
          disabled={isLoading}
          title="साफ़ करें"
        >
          <span className="action-btn-icon">🗑️</span>
          <span className="action-btn-label">साफ़</span>
        </button>
      </div>
    </div>
  );
};
