import React from "react";
import { SpellingIssue } from "../../spellcheck";

interface SpellCheckPanelProps {
  issues: SpellingIssue[];
  onApplySuggestion: (issue: SpellingIssue, suggestion: string) => void;
  onIgnoreWord: (word: string) => void;
  onAddWordToDictionary: (word: string) => void;
  onClose: () => void;
}

export const SpellCheckPanel: React.FC<SpellCheckPanelProps> = ({
  issues,
  onApplySuggestion,
  onIgnoreWord,
  onAddWordToDictionary,
  onClose,
}) => {
  if (issues.length === 0) {
    return (
      <div className="spellcheck-panel spellcheck-panel-clean">
        <div className="spellcheck-clean-content">
          <span className="clean-icon">✅</span>
          <div>
            <h3 className="clean-title">कोई वर्तनी त्रुटि नहीं मिली!</h3>
            <p className="clean-subtitle">आपका हिन्दी पाठ व्याकरण एवं वर्तनी की दृष्टि से शुद्ध प्रतीत होता है।</p>
          </div>
        </div>
        <button className="spellcheck-close-btn" onClick={onClose} title="बंद करें">
          ✕
        </button>
      </div>
    );
  }

  return (
    <div className="spellcheck-panel">
      <div className="spellcheck-header">
        <div className="spellcheck-header-title">
          <span className="spellcheck-icon">🔍</span>
          <span className="spellcheck-title">वर्तनी सुझाव</span>
          <span className="spellcheck-badge">{issues.length} अशुद्धियाँ</span>
        </div>
        <button className="spellcheck-close-btn" onClick={onClose} title="बंद करें">
          ✕
        </button>
      </div>

      <div className="spellcheck-list">
        {issues.map((issue) => (
          <div key={issue.id} className="spellcheck-card">
            <div className="spellcheck-card-top">
              <span className="misspelled-word">
                {issue.word}
              </span>
              <span className="card-context">
                {issue.context}
              </span>
            </div>

            <div className="suggestion-section">
              <span className="suggestion-label">सुझाव:</span>
              <div className="suggestion-chips">
                {issue.suggestions.length > 0 ? (
                  issue.suggestions.map((sug, idx) => (
                    <button
                      key={idx}
                      className="suggestion-chip"
                      onClick={() => onApplySuggestion(issue, sug)}
                      title={`"${issue.word}" को "${sug}" से बदलें`}
                    >
                      <span className="chip-icon">✓</span>
                      <span className="chip-text">{sug}</span>
                    </button>
                  ))
                ) : (
                  <span className="no-suggestions">कोई सीधा सुझाव उपलब्ध नहीं</span>
                )}
              </div>
            </div>

            <div className="spellcheck-card-actions">
              <button
                className="action-link-btn"
                onClick={() => onIgnoreWord(issue.word)}
                title="इस सत्र के लिए अनदेखा करें"
              >
                👁️ अनदेखा करें
              </button>
              <button
                className="action-link-btn action-link-dict"
                onClick={() => onAddWordToDictionary(issue.word)}
                title="इस शब्द को निजी शब्दकोश में जोड़ें ताकि भविष्य में त्रुटि न माने"
              >
                📖 शब्दकोश में जोड़ें
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
