import React, { useState } from "react";

interface DocumentToolsPanelProps {
  onScanFullDocument: () => void;
  onConvertEntireDocToUnicode: () => void;
  onConvertEntireDocToKrutiDev: () => void;
  onFindInWord: (query: string) => void;
  isLoading: boolean;
  docStats?: {
    paragraphs: number;
    words: number;
    chars: number;
    hasKrutiDev: boolean;
  };
  onClose: () => void;
}

export const DocumentToolsPanel: React.FC<DocumentToolsPanelProps> = ({
  onScanFullDocument,
  onConvertEntireDocToUnicode,
  onConvertEntireDocToKrutiDev,
  onFindInWord,
  isLoading,
  docStats,
  onClose,
}) => {
  const [showConfirmUnicode, setShowConfirmUnicode] = useState<boolean>(false);
  const [showConfirmKrutiDev, setShowConfirmKrutiDev] = useState<boolean>(false);
  const [searchQuery, setSearchQuery] = useState<string>("");

  return (
    <div className="document-tools-panel">
      <div className="doc-tools-header">
        <div className="doc-tools-title-box">
          <span className="doc-tools-icon">📑</span>
          <span className="doc-tools-title">पूरा दस्तावेज़ प्रबंधन</span>
        </div>
        <button className="spellcheck-close-btn" onClick={onClose} title="बंद करें">
          ✕
        </button>
      </div>

      {docStats && (
        <div className="doc-stats-grid">
          <div className="stat-card">
            <span className="stat-num">{docStats.paragraphs}</span>
            <span className="stat-label">अनुच्छेद (Paragraphs)</span>
          </div>
          <div className="stat-card">
            <span className="stat-num">{docStats.words}</span>
            <span className="stat-label">कुल शब्द (Words)</span>
          </div>
          <div className="stat-card">
            <span className="stat-num">{docStats.chars}</span>
            <span className="stat-label">कुल अक्षर (Chars)</span>
          </div>
          <div className="stat-card">
            <span className="stat-num">{docStats.hasKrutiDev ? "हाँ (Yes)" : "नहीं"}</span>
            <span className="stat-label">Kruti Dev उपस्थित</span>
          </div>
        </div>
      )}

      {/* Action 1: Comprehensive Scan */}
      <div className="doc-action-group">
        <button
          className="doc-primary-btn"
          onClick={onScanFullDocument}
          disabled={isLoading}
        >
          <span className="btn-icon">🔍</span>
          <span>पूरे दस्तावेज़ की वर्तनी एवं व्याकरण जाँच</span>
        </button>
      </div>

      {/* Action 2: Batch Document Conversion */}
      <div className="doc-action-group">
        <span className="group-label">दस्तावेज़-व्यापी रूपांतरण (Document-wide Conversion):</span>
        
        {!showConfirmUnicode && !showConfirmKrutiDev && (
          <div className="action-row">
            <button
              className="action-btn action-btn-primary"
              onClick={() => setShowConfirmUnicode(true)}
              disabled={isLoading}
              title="पूरे दस्तावेज़ को Unicode में बदलें और फॉन्ट Mangal करें"
            >
              <span className="action-btn-icon">🔤</span>
              <span className="action-btn-label">पूरा Kruti Dev ➔ Unicode</span>
            </button>
            <button
              className="action-btn action-btn-secondary"
              onClick={() => setShowConfirmKrutiDev(true)}
              disabled={isLoading}
              title="पूरे दस्तावेज़ को Kruti Dev 010 में बदलें"
            >
              <span className="action-btn-icon">🔡</span>
              <span className="action-btn-label">पूरा Unicode ➔ Kruti Dev</span>
            </button>
          </div>
        )}

        {showConfirmUnicode && (
          <div className="confirm-box">
            <p className="confirm-text">
              ⚠️ क्या आप <strong>पूरे दस्तावेज़</strong> के Kruti Dev पाठ को Unicode में बदलना चाहते हैं? फॉन्ट भी 'Mangal' में बदल दिया जाएगा।
            </p>
            <div className="confirm-actions">
              <button
                className="confirm-yes-btn"
                onClick={() => {
                  setShowConfirmUnicode(false);
                  onConvertEntireDocToUnicode();
                }}
              >
                ✓ हाँ, बदलें
              </button>
              <button
                className="confirm-cancel-btn"
                onClick={() => setShowConfirmUnicode(false)}
              >
                रद्द करें
              </button>
            </div>
          </div>
        )}

        {showConfirmKrutiDev && (
          <div className="confirm-box">
            <p className="confirm-text">
              ⚠️ क्या आप <strong>पूरे दस्तावेज़</strong> को Kruti Dev 010 में बदलना चाहते हैं? फॉन्ट 'Kruti Dev 010' सेट होगा।
            </p>
            <div className="confirm-actions">
              <button
                className="confirm-yes-btn"
                onClick={() => {
                  setShowConfirmKrutiDev(false);
                  onConvertEntireDocToKrutiDev();
                }}
              >
                ✓ हाँ, बदलें
              </button>
              <button
                className="confirm-cancel-btn"
                onClick={() => setShowConfirmKrutiDev(false)}
              >
                रद्द करें
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Action 3: Find and Highlight in Word Document */}
      <div className="doc-action-group">
        <span className="group-label">Word दस्तावेज़ में सीधे खोजें एवं हाइलाइट करें:</span>
        <div className="find-box">
          <input
            type="text"
            className="find-input"
            placeholder="खोजने के लिए शब्द लिखें..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && searchQuery.trim()) {
                onFindInWord(searchQuery.trim());
              }
            }}
          />
          <button
            className="find-btn"
            onClick={() => onFindInWord(searchQuery.trim())}
            disabled={!searchQuery.trim() || isLoading}
          >
            खोजें
          </button>
        </div>
      </div>
    </div>
  );
};
