export function searchGlossary(query: string): GlossaryTerm[] {
  if (!query || !query.trim()) return [];
  const q = query.trim().toLowerCase();
  const qNormalized = q.replace(/\u093C/g, ""); // remove nukta for tolerant Hindi search
  return ADMINISTRATIVE_GLOSSARY.filter(item => {
    const enMatch = item.english.toLowerCase().includes(q);
    const hiMatch = item.hindi.toLowerCase().includes(q);
    const hiNormMatch = item.hindi.replace(/\u093C/g, "").toLowerCase().includes(qNormalized);
    return enMatch || hiMatch || hiNormMatch;
  });
}
