import React, { useState } from "react";
import { LETTER_TEMPLATES, searchGlossary, ADMINISTRATIVE_GLOSSARY, LetterTemplate, GlossaryTerm } from "../../templates";
import { unicodeToKrutiDev } from "../../krutidev";

interface TemplatesPanelProps {
  onLoadIntoEditor: (text: string) => void;
  onInsertIntoWord: (text: string, fontName: string) => void;
  onClose: () => void;
}

export const TemplatesPanel: React.FC<TemplatesPanelProps> = ({
  onLoadIntoEditor,
  onInsertIntoWord,
  onClose,
}) => {
  const [activeTab, setActiveTab] = useState<"templates" | "glossary">("templates");

  // Template State
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>(LETTER_TEMPLATES[0].id);
  const selectedTemplate: LetterTemplate =
    LETTER_TEMPLATES.find((t) => t.id === selectedTemplateId) || LETTER_TEMPLATES[0];

  // Initialize form field values from template defaults
  const [fieldValues, setFieldValues] = useState<Record<string, Record<string, string>>>(() => {
    const initial: Record<string, Record<string, string>> = {};
    for (const t of LETTER_TEMPLATES) {
      initial[t.id] = {};
      for (const f of t.fields) {
        initial[t.id][f.key] = f.defaultValue;
      }
    }
    return initial;
  });

  const currentValues = fieldValues[selectedTemplate.id] || {};

  const handleFieldChange = (key: string, val: string) => {
    setFieldValues((prev) => ({
      ...prev,
      [selectedTemplate.id]: {
        ...(prev[selectedTemplate.id] || {}),
        [key]: val,
      },
    }));
  };

  // Font output selection
  const [outputFont, setOutputFont] = useState<"unicode" | "krutidev">("unicode");

  // Live generated letter
  const generatedUnicodeText = selectedTemplate.generateText(currentValues);
  const finalText =
    outputFont === "krutidev" ? unicodeToKrutiDev(generatedUnicodeText) : generatedUnicodeText;

  // Glossary State
  const [glossaryQuery, setGlossaryQuery] = useState<string>("");
  const glossaryResults: GlossaryTerm[] = glossaryQuery.trim()
    ? searchGlossary(glossaryQuery)
    : ADMINISTRATIVE_GLOSSARY.slice(0, 15);

  return (
    <div className="templates-panel">
      <div className="templates-header">
        <div className="templates-title-box">
          <span className="templates-icon">📝</span>
          <span className="templates-title">पत्र प्रारूप एवं प्रशासनिक शब्दावली</span>
        </div>
        <button className="spellcheck-close-btn" onClick={onClose} title="बंद करें">
          ✕
        </button>
      </div>

      {/* Tabs */}
      <div className="templates-tabs">
        <button
          className={`templates-tab ${activeTab === "templates" ? "active" : ""}`}
          onClick={() => setActiveTab("templates")}
        >
          📄 पत्र प्रारूप (Templates)
        </button>
        <button
          className={`templates-tab ${activeTab === "glossary" ? "active" : ""}`}
          onClick={() => setActiveTab("glossary")}
        >
          📖 प्रशासनिक शब्दावली (Glossary)
        </button>
      </div>

      {activeTab === "templates" && (
        <div className="template-content">
          {/* Template Selector */}
          <div className="template-selector-group">
            <label className="field-label">प्रारूप चुनें (Select Letter Type):</label>
            <select
              className="template-select"
              value={selectedTemplateId}
              onChange={(e) => setSelectedTemplateId(e.target.value)}
            >
              {LETTER_TEMPLATES.map((tmpl) => (
                <option key={tmpl.id} value={tmpl.id}>
                  {tmpl.title} ({tmpl.categoryLabel})
                </option>
              ))}
            </select>
            <p className="template-desc">{selectedTemplate.description}</p>
          </div>

          {/* Form Fields for the Template */}
          <div className="template-form-fields">
            {selectedTemplate.fields.map((f) => (
              <div key={f.key} className="form-field-group">
                <label className="field-label">{f.label}:</label>
                {f.key === "bodyDetail" || f.key === "issueDetails" || f.key === "requestedInfo" || f.key === "memoBody" || f.key === "copyTo" ? (
                  <textarea
                    className="field-textarea"
                    rows={3}
                    placeholder={f.placeholder}
                    value={currentValues[f.key] ?? f.defaultValue}
                    onChange={(e) => handleFieldChange(f.key, e.target.value)}
                  />
                ) : (
                  <input
                    type="text"
                    className="field-input"
                    placeholder={f.placeholder}
                    value={currentValues[f.key] ?? f.defaultValue}
                    onChange={(e) => handleFieldChange(f.key, e.target.value)}
                  />
                )}
              </div>
            ))}
          </div>

          {/* Font Toggle & Actions */}
          <div className="template-actions-box">
            <div className="font-toggle-box">
              <span className="font-toggle-label">आउटपुट फॉन्ट (Output Format):</span>
              <div className="radio-options">
                <label className="radio-label">
                  <input
                    type="radio"
                    name="outputFont"
                    value="unicode"
                    checked={outputFont === "unicode"}
                    onChange={() => setOutputFont("unicode")}
                  />
                  <span>Unicode (मंगल / मानक हिन्दी)</span>
                </label>
                <label className="radio-label">
                  <input
                    type="radio"
                    name="outputFont"
                    value="krutidev"
                    checked={outputFont === "krutidev"}
                    onChange={() => setOutputFont("krutidev")}
                  />
                  <span>Kruti Dev 010</span>
                </label>
              </div>
            </div>

            <div className="template-btn-row">
              <button
                className="template-load-btn"
                onClick={() => onLoadIntoEditor(finalText)}
                title="संपादक में लोड करें ताकि आप इसमें और बदलाव कर सकें"
              >
                ✏️ संपादक में लोड करें
              </button>
              <button
                className="template-insert-btn"
                onClick={() =>
                  onInsertIntoWord(
                    finalText,
                    outputFont === "krutidev" ? "Kruti Dev 010" : "Mangal"
                  )
                }
                title="सीधे Microsoft Word दस्तावेज़ में डालें"
              >
                📋 सीधे Word में डालें
              </button>
            </div>
          </div>

          {/* Live Preview */}
          <div className="template-preview-box">
            <span className="preview-label">लाइव पूर्वावलोकन (Live Preview):</span>
            <pre className={`preview-text ${outputFont === "krutidev" ? "krutidev-text" : ""}`}>
              {finalText}
            </pre>
          </div>
        </div>
      )}

      {activeTab === "glossary" && (
        <div className="glossary-content">
          <div className="glossary-search-box">
            <input
              type="text"
              className="find-input"
              placeholder="अंग्रेजी या हिन्दी शब्द खोजें (उदा: Sanction, Approval, कार्रवाई)..."
              value={glossaryQuery}
              onChange={(e) => setGlossaryQuery(e.target.value)}
            />
          </div>

          <div className="glossary-table-container">
            <table className="glossary-table">
              <thead>
                <tr>
                  <th>अंग्रेजी शब्द</th>
                  <th>मानक सरकारी हिन्दी</th>
                  <th>उपयोग संदर्भ</th>
                </tr>
              </thead>
              <tbody>
                {glossaryResults.length > 0 ? (
                  glossaryResults.map((item, idx) => (
                    <tr key={idx}>
                      <td className="glossary-en">{item.english}</td>
                      <td className="glossary-hi">{item.hindi}</td>
                      <td className="glossary-usage">{item.usage || "—"}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={3} className="no-data">
                      कोई परिणाम नहीं मिला।
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};
