import { GrammarIssue, GrammarRule } from "./types";
import { REDUNDANCY_RULES } from "./rules/redundancyRules";
import { ADMINISTRATIVE_STYLE_RULES } from "./rules/administrativeStyleRules";
import { AGREEMENT_RULES } from "./rules/agreementRules";

export const ALL_GRAMMAR_RULES: GrammarRule[] = [
  ...REDUNDANCY_RULES,
  ...ADMINISTRATIVE_STYLE_RULES,
  ...AGREEMENT_RULES,
];

function getGrammarContext(text: string, start: number, end: number, padding: number = 30): string {
  const cStart = Math.max(0, start - padding);
  const cEnd = Math.min(text.length, end + padding);
  const prefix = cStart > 0 ? "..." : "";
  const suffix = cEnd < text.length ? "..." : "";
  return prefix + text.slice(cStart, cEnd) + suffix;
}

export function checkHindiGrammar(
  text: string,
  ignoredRuleIds?: Set<string>
): GrammarIssue[] {
  if (!text || !text.trim()) {
    return [];
  }

  const issues: GrammarIssue[] = [];
  const occupiedSpans: { start: number; end: number }[] = [];

  function isOverlapping(start: number, end: number): boolean {
    return occupiedSpans.some(span => 
      (start >= span.start && start < span.end) ||
      (end > span.start && end <= span.end) ||
      (start <= span.start && end >= span.end)
    );
  }

  for (const rule of ALL_GRAMMAR_RULES) {
    if (ignoredRuleIds && ignoredRuleIds.has(rule.id)) {
      continue;
    }

    // Reset regex state
    rule.pattern.lastIndex = 0;

    let match: RegExpExecArray | null;
    while ((match = rule.pattern.exec(text)) !== null) {
      const matchText = match[0];
      const start = match.index;
      const end = start + matchText.length;

      // Skip overlapping matches
      if (isOverlapping(start, end)) {
        continue;
      }

      // Generate replacement
      const replacement = rule.replace(matchText, ...match.slice(1));
      if (replacement === matchText) {
        continue;
      }

      const context = getGrammarContext(text, start, end);

      issues.push({
        id: `gram-${rule.id}-${start}`,
        category: rule.category,
        categoryLabel: rule.categoryLabel,
        title: rule.title,
        explanation: rule.explanation,
        original: matchText,
        replacement,
        start,
        end,
        context,
      });

      occupiedSpans.push({ start, end });
    }
  }

  // Sort issues by appearance in text
  issues.sort((a, b) => a.start - b.start);

  return issues;
}
