import { HINDI_BASE_WORD_SET, HINDI_BASE_WORDS } from "./baseWords";
import { getCustomWords, addCustomWord, removeCustomWord, clearPersonalDictionary } from "./personalDictionary";

export { HINDI_BASE_WORDS, getCustomWords, addCustomWord, removeCustomWord, clearPersonalDictionary };

/**
 * Check if a word exists in either the base dictionary or personal dictionary.
 */
export function isKnownWord(word: string, customWords?: Set<string>): boolean {
  const cleaned = word.trim();
  if (!cleaned) return true;

  if (HINDI_BASE_WORD_SET.has(cleaned)) {
    return true;
  }

  if (customWords && customWords.has(cleaned)) {
    return true;
  }

  // Check personal dictionary if not passed
  const personal = customWords ? null : new Set(getCustomWords());
  if (personal && personal.has(cleaned)) {
    return true;
  }

  return false;
}

/**
 * Returns a combined list of all unique known words for suggestion matching.
 */
export function getAllKnownWords(): string[] {
  const custom = getCustomWords();
  return [...HINDI_BASE_WORDS, ...custom];
}
