import { WordToken } from "./types";

/**
 * Tokenizes text into Devanagari Hindi word tokens with start and end offsets.
 * Filters out pure numbers, punctuation, danda, and non-Hindi tokens.
 */
export function tokenizeHindiText(text: string): WordToken[] {
  const tokens: WordToken[] = [];
  // Matches Devanagari words: characters in range U+0900 to U+097F, including ZWJ/ZWNJ
  // Excludes danda (U+0964) and double danda (U+0965)
  const regex = /[\u0904-\u0939\u093D-\u0950\u0958-\u0961\u0962-\u0963\u0970-\u097F\u093E-\u094D\u0901-\u0903\u200C\u200D]+/g;

  let match: RegExpExecArray | null;
  while ((match = regex.exec(text)) !== null) {
    const rawWord = match[0];
    const start = match.index;
    const end = start + rawWord.length;

    // Filter out if it's purely digits (Devanagari ०-९)
    if (/^[\u0966-\u096F]+$/.test(rawWord)) {
      continue;
    }

    // Filter out isolated halants or single matras
    if (/^[\u093E-\u094D\u0901-\u0903\u093C]+$/.test(rawWord)) {
      continue;
    }

    tokens.push({
      word: rawWord,
      start,
      end,
    });
  }

  return tokens;
}

/**
 * Extracts contextual snippet around a given word offset.
 */
export function getWordContext(text: string, start: number, end: number, padding: number = 25): string {
  const contextStart = Math.max(0, start - padding);
  const contextEnd = Math.min(text.length, end + padding);

  const prefix = contextStart > 0 ? "..." : "";
  const suffix = contextEnd < text.length ? "..." : "";

  return prefix + text.slice(contextStart, contextEnd) + suffix;
}
