import { KRUTIDEV_TO_UNICODE_MAP } from './mappings';

function isDevanagariConsonant(code: number): boolean {
  return (code >= 0x0915 && code <= 0x0939) || (code >= 0x0958 && code <= 0x095F);
}

function isDevanagariMatra(code: number): boolean {
  return (
    (code >= 0x093E && code <= 0x094C) ||
    code === 0x0962 ||
    code === 0x0963 ||
    code === 0x0901 ||
    code === 0x0902 ||
    code === 0x0903 ||
    code === 0x093C
  );
}

export function krutiDevToUnicode(input: string): string {
  let result = input;
  
  // 1. Apply all substitutions in sequence
  for (const [krutidev, unicode] of KRUTIDEV_TO_UNICODE_MAP) {
    if (krutidev === "" || krutidev === undefined) continue;
    result = result.split(krutidev).join(unicode);
  }
  
  // 2. Post-process special placeholder tokens
  
  // Process α (ि / chhoti i reordering) - moves AFTER the consonant cluster
  while (result.includes('α')) {
    const idx = result.indexOf('α');
    result = result.slice(0, idx) + result.slice(idx + 1);
    let end = idx;
    if (end < result.length && isDevanagariConsonant(result.charCodeAt(end))) {
      end++;
      while (
        end < result.length - 1 && 
        result.charCodeAt(end) === 0x094D && 
        isDevanagariConsonant(result.charCodeAt(end + 1))
      ) {
        end += 2;
      }
    }
    result = result.slice(0, end) + 'ि' + result.slice(end);
  }
  
  // Process β (िं / chhoti i + anusvaar reordering)
  while (result.includes('β')) {
    const idx = result.indexOf('β');
    result = result.slice(0, idx) + result.slice(idx + 1);
    let end = idx;
    if (end < result.length && isDevanagariConsonant(result.charCodeAt(end))) {
      end++;
      while (
        end < result.length - 1 && 
        result.charCodeAt(end) === 0x094D && 
        isDevanagariConsonant(result.charCodeAt(end + 1))
      ) {
        end += 2;
      }
    }
    result = result.slice(0, end) + 'िं' + result.slice(end);
  }
  
  // Process γ (र् / reph reordering)
  // In KrutiDev, Z appears AFTER the character it sits on.
  // In Unicode Devanagari, र् must precede the consonant cluster.
  while (result.includes('γ')) {
    const idx = result.indexOf('γ');
    result = result.slice(0, idx) + result.slice(idx + 1);
    let pos = idx - 1;
    // Skip backward over any matras, anusvaar, or nukta attached to the base consonant
    while (pos >= 0 && isDevanagariMatra(result.charCodeAt(pos))) {
      pos--;
    }
    if (pos >= 0 && isDevanagariConsonant(result.charCodeAt(pos))) {
      // If preceded by halant + consonant, move before the entire conjunct
      while (
        pos >= 2 && 
        result.charCodeAt(pos - 1) === 0x094D && 
        isDevanagariConsonant(result.charCodeAt(pos - 2))
      ) {
        pos -= 2;
      }
      result = result.slice(0, pos) + 'र्' + result.slice(pos);
    } else {
      result = result.slice(0, idx) + 'र्' + result.slice(idx);
    }
  }
  
  return result;
}

const UNICODE_TO_KRUTIDEV_BASE: Record<string, string> = {
  'अ': 'v', 'आ': 'vk', 'इ': 'b', 'ई': 'bZ', 'उ': 'm', 'ऊ': 'Å',
  'ऋ': '_', 'ए': ',', 'ऐ': ',s', 'ओ': 'vks', 'औ': 'vkS',
  'क': 'd', 'क्': 'D', 'ख': '[k', 'ख्': '[', 'ग': 'x', 'ग्': 'X',
  'घ': '?k', 'घ्': '?', 'ङ': '³',
  'च': 'p', 'च्': 'P', 'छ': 'N', 'ज': 't', 'ज्': 'T', 'झ': '>', 'झ्': '÷',
  'ञ': '¥', 'ट': 'V', 'ठ': 'B', 'ड': 'M', 'ढ': '<', 'ण': '.k', 'ण्': '.',
  'त': 'r', 'त्': 'R', 'थ': 'Fk', 'थ्': 'F', 'द': 'n', 'ध': '/k', 'ध्': '/',
  'न': 'u', 'न्': 'U', 'प': 'i', 'प्': 'I', 'फ': 'Q', 'फ्': '¶',
  'ब': 'c', 'ब्': 'C', 'भ': 'Hk', 'भ्': 'H', 'म': 'e', 'म्': 'E',
  'य': ';', 'य्': '¸', 'र': 'j', 'ल': 'y', 'ल्': 'Y', 'व': 'o', 'व्': 'O',
  'श': '\'k', 'श्': '\'', 'ष': '\"k', 'ष्': '\"', 'स': 'l', 'स्': 'L', 'ह': 'g',
  'क्ष': '{k', 'क्ष्': '{', 'त्र': '=', 'त्र्': '«', 'ज्ञ': 'K', 'श्र': 'J',
  'ा': 'k', 'ि': 'f', 'ी': 'h', 'ु': 'q', 'ू': 'w', 'ृ': '`',
  'े': 's', 'ै': 'S', 'ो': 'ks', 'ौ': 'kS', 'ं': 'a', 'ँ': '¡', 'ः': '%',
  '्': '~', '।': 'A', '०': 'å', '१': 'ƒ', '२': '„', '३': '…',
  '४': '†', '५': '‡', '६': 'ˆ', '७': '‰', '८': 'Š', '९': '‹',
  ',': ']', ';': '(', '?': '\\', '!': '!'
};

const sortedUnicodeKeys = Object.keys(UNICODE_TO_KRUTIDEV_BASE).sort((a, b) => b.length - a.length);
const reverseRegex = new RegExp(
  sortedUnicodeKeys.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'),
  'g'
);

export function unicodeToKrutiDev(input: string): string {
  let result = input;
  
  // 1. Move reph (र्) before consonant cluster to after the cluster as Z
  const rephRegex = /र्([\u0915-\u0939\u0958-\u095F](?:\u094D[\u0915-\u0939\u0958-\u095F])*(?:[\u093E-\u094C\u0962\u0963\u0901\u0902\u0903\u093C]*))/g;
  result = result.replace(rephRegex, '$1Z');
  
  // 2. Move chhoti i (ि) from after consonant cluster to before as f
  const clusterRegex = /([\u0915-\u0939\u0958-\u095F](?:\u094D[\u0915-\u0939\u0958-\u095F])*)ि/g;
  result = result.replace(clusterRegex, 'f$1');
  
  // 3. Single-pass tokenized replacement prevents double mapping
  return result.replace(reverseRegex, matched => UNICODE_TO_KRUTIDEV_BASE[matched]);
}

export function isKrutiDevText(text: string): boolean {
  if (!text || !text.trim()) return false;
  
  // If text contains Devanagari Unicode characters (U+0900-U+097F), it is NOT Kruti Dev
  if (/[\u0900-\u097F]/.test(text)) {
    return false;
  }
  
  // If it has extended Latin characters commonly used by Kruti Dev fonts
  if (/[\u00A0-\u00FF\u0100-\u024F\u2010-\u203A]/.test(text)) {
    return true;
  }
  
  // Common Kruti Dev words / particles
  const commonKdWords = /\b(lsok|esa|Hkkjr|ljdkj|fcgkj|uxj|Jheku|djuk|gS|gSa|dh|ds|dk|dks|Fkk|Fks|Fkh|dj|djs|ls|ij|rFkk|,oa|;k|ugha|gks|gksrk|fn;k|fy;k|fd|vkSj|vkidk|vkids|vkidh|egksn;)\b/i;
  if (commonKdWords.test(text)) {
    return true;
  }
  
  // High frequency Kruti Dev bigrams and patterns (like 'vk', 'kZ', 'dZ', 'ok', etc.)
  const kdPatterns = /(?:vk|kS|ks|bZ|Z[a-zA-Z]|[a-zA-Z]Z|f[a-zA-Z]|\[\+|T\+|t\+|M\+|<\+|Q\+|\/keZ|dkeZ|dk;Z)/;
  if (kdPatterns.test(text)) {
    return true;
  }
  
  return false;
}
