import { GrammarRule, createRulePattern } from "../types";

export const AGREEMENT_RULES: GrammarRule[] = [
  {
    id: "agr-aap-karta-hai",
    category: "agreement",
    categoryLabel: "व्याकरणिक अन्विति",
    title: "'आप' के साथ आदरसूचक क्रिया 'करते हैं / करते हों'",
    explanation: "सर्वनाम 'आप' आदरसूचक होने के कारण सदैव बहुवचन क्रिया लेता है। 'आप करता है' अशुद्ध है, 'आप करते हैं' लिखें।",
    pattern: createRulePattern("आप\\s+([^।?!,]+?)\\s+(करता|करती)\\s+है"),
    replace: (_m, middle, gender) => {
      const v = gender === "करती" ? "करती हैं" : "करते हैं";
      return `आप ${middle} ${v}`;
    },
  },
  {
    id: "agr-hum-karta-hoon",
    category: "agreement",
    categoryLabel: "व्याकरणिक अन्विति",
    title: "'हम' के साथ 'करते हैं' अथवा 'मैं' के साथ 'करता हूँ'",
    explanation: "'हम' बहुवचन सर्वनाम है, इसके साथ 'करते हैं' आता है। यदि एकवचन का बोध कराना हो तो 'मैं करता हूँ' लिखें।",
    pattern: createRulePattern("हम\\s+([^।?!,]+?)\\s+(करता|करती)\\s+हूँ"),
    replace: (_m, middle, gender) => {
      const v = gender === "करती" ? "करती हैं" : "करते हैं";
      return `हम ${middle} ${v}`;
    },
  },
  {
    id: "agr-ve-aaya",
    category: "agreement",
    categoryLabel: "व्याकरणिक अन्विति",
    title: "'वे' के साथ बहुवचन क्रिया 'आए / गए'",
    explanation: "सर्वनाम 'वे' अन्य पुरुष बहुवचन है, इसके साथ एकवचन क्रिया (आया, गया) के स्थान पर बहुवचन क्रिया (आए, गए) का प्रयोग होता है।",
    pattern: createRulePattern("(वे|वे\\s+लोग)\\s+(आया|गया|बोला|कहा)\\s*(है|था)?"),
    replace: (_m, pronoun, verb, aux) => {
      const verbMap: Record<string, string> = {
        "आया": "आए",
        "गया": "गए",
        "बोला": "बोले",
        "कहा": "कहे",
      };
      const auxMap: Record<string, string> = {
        "है": "हैं",
        "था": "थे",
      };
      const v = verbMap[verb] || verb;
      const a = aux ? (auxMap[aux] || aux) : "";
      return `${pronoun} ${v}${a ? " " + a : ""}`.trim();
    },
  },
  {
    id: "agr-honorific-pitaji",
    category: "honorific",
    categoryLabel: "आदरार्थक प्रयोग",
    title: "सम्माननीय व्यक्ति के साथ आदरार्थक बहुवचन क्रिया",
    explanation: "पिताजी, अधिकारी, गुरुजन आदि आदरणीय संज्ञाओं के साथ एकवचन क्रिया के स्थान पर आदरार्थक बहुवचन क्रिया ('आए हैं', 'कहा है') का प्रयोग होता है।",
    pattern: createRulePattern("(पिताजी|माताजी|गुरुजी|अधिकारी|जिलाधिकारी|महोदय)\\s+(आया|गया|बोला)\\s+है"),
    replace: (_m, subject, verb) => {
      const verbMap: Record<string, string> = {
        "आया": "आए हैं",
        "गया": "गए हैं",
        "बोला": "बोले हैं",
      };
      return `${subject} ${verbMap[verb] || verb}`;
    },
  },
  {
    id: "agr-ke-dwara-se",
    category: "agreement",
    categoryLabel: "कारक प्रयोग",
    title: "'के द्वारा से' के स्थान पर केवल 'के द्वारा'",
    explanation: "'के द्वारा' अपने आप में करण कारक का परसर्ग है। इसके बाद 'से' लगाना व्याकरणिक रूप से अशुद्ध है।",
    pattern: createRulePattern("के\\s+द्वारा\\s+से"),
    replace: () => "के द्वारा",
  },
  {
    id: "agr-faisla-liya",
    category: "agreement",
    categoryLabel: "व्याकरणिक अन्विति",
    title: "'फैसला लिया' (पुल्लिंग कर्म के अनुसार क्रिया)",
    explanation: "'ने' विभक्ति वाले वाक्यों में क्रिया कर्म के लिंग अनुसार होती है। 'फैसला' पुल्लिंग है, अतः 'फैसला ली' के स्थान पर 'फैसला लिया' होगा।",
    pattern: createRulePattern("फैसला\\s+ली"),
    replace: () => "फैसला लिया",
  },
  {
    id: "agr-aadesh-di",
    category: "agreement",
    categoryLabel: "व्याकरणिक अन्विति",
    title: "'आदेश दिया' (पुल्लिंग कर्म के अनुसार क्रिया)",
    explanation: "'आदेश' पुल्लिंग शब्द है, अतः 'आदेश दी' के स्थान पर 'आदेश दिया' अथवा 'आदेश दिए' शुद्ध है।",
    pattern: createRulePattern("आदेश\\s+दी"),
    replace: () => "आदेश दिया",
  }
];
