import React, { useState, useCallback } from "react";
import { Header, FontSizeScale } from "./components/Header";
import { TextDisplay } from "./components/TextDisplay";
import { ActionBar } from "./components/ActionBar";
import { StatusBar } from "./components/StatusBar";
import { ConversionBar } from "./components/ConversionBar";
import { SpellCheckPanel } from "./components/SpellCheckPanel";
import { GrammarPanel } from "./components/GrammarPanel";
import { DocumentToolsPanel } from "./components/DocumentToolsPanel";
import { TemplatesPanel } from "./components/TemplatesPanel";
import { HelpModal } from "./components/HelpModal";
import {
  getSelectedText,
  replaceSelectedText,
  getDocumentBody,
  getSelectionInfo,
  replaceDocumentBody,
  searchAndSelectInDocument,
  getDocumentParagraphs,
} from "../office/wordApi";
import { krutiDevToUnicode, unicodeToKrutiDev, isKrutiDevText } from "../krutidev";
import { checkHindiSpelling, SpellingIssue } from "../spellcheck";
import { checkHindiGrammar, GrammarIssue } from "../grammar";
import { addCustomWord } from "../dictionary";

export const App: React.FC = () => {
  const [selectedText, setSelectedText] = useState<string>("");
  const [editedText, setEditedText] = useState<string>("");
  const [status, setStatus] = useState<string>("तैयार है। Word में text चुनें और 'चयन पढ़ें' दबाएँ।");
  const [statusType, setStatusType] = useState<"success" | "error" | "info">("info");
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [fontDetected, setFontDetected] = useState<string>("");
  const [isKrutiDev, setIsKrutiDev] = useState<boolean>(false);

  // Spell check state
  const [spellingIssues, setSpellingIssues] = useState<SpellingIssue[]>([]);
  const [showSpellPanel, setShowSpellPanel] = useState<boolean>(false);
  const [ignoredWords, setIgnoredWords] = useState<Set<string>>(new Set());

  // Grammar check state
  const [grammarIssues, setGrammarIssues] = useState<GrammarIssue[]>([]);
  const [showGrammarPanel, setShowGrammarPanel] = useState<boolean>(false);
  const [ignoredGrammarRuleIds, setIgnoredGrammarRuleIds] = useState<Set<string>>(new Set());

  // Document Tools & Templates state
  const [showDocTools, setShowDocTools] = useState<boolean>(false);
  const [showTemplates, setShowTemplates] = useState<boolean>(false);
  const [docStats, setDocStats] = useState<{
    paragraphs: number;
    words: number;
    chars: number;
    hasKrutiDev: boolean;
  }>({ paragraphs: 0, words: 0, chars: 0, hasKrutiDev: false });

  // Accessibility & Settings state
  const [fontSizeScale, setFontSizeScale] = useState<FontSizeScale>(() => {
    try {
      return (localStorage.getItem("hindi_assistant_font_scale") as FontSizeScale) || "normal";
    } catch {
      return "normal";
    }
  });
  const [showHelp, setShowHelp] = useState<boolean>(false);

  const handleFontSizeChange = useCallback((scale: FontSizeScale) => {
    setFontSizeScale(scale);
    try {
      localStorage.setItem("hindi_assistant_font_scale", scale);
    } catch {
      // ignore storage error
    }
  }, []);

  const showStatus = useCallback((message: string, type: "success" | "error" | "info") => {
    setStatus(message);
    setStatusType(type);
  }, []);

  const handleReadSelection = useCallback(async () => {
    setIsLoading(true);
    try {
      const info = await getSelectionInfo();
      if (!info.text.trim()) {
        showStatus("कोई text चयनित नहीं है। पहले Word में text चुनें।", "error");
        setIsLoading(false);
        return;
      }
      setSelectedText(info.text);
      setEditedText(info.text);
      setFontDetected(info.fontName);
      setSpellingIssues([]);
      setShowSpellPanel(false);
      setGrammarIssues([]);
      setShowGrammarPanel(false);
      setShowTemplates(false);

      const detectedKD = isKrutiDevText(info.text) || isKrutiDev;
      setIsKrutiDev(detectedKD || info.fontName.toLowerCase().includes('kruti') || info.fontName.toLowerCase().includes('krdv'));

      const isKrutiDevLocal = info.fontName.toLowerCase().includes("kruti") || info.fontName.toLowerCase().includes("krdv");
      const fontMsg = info.fontName ? ` (Font: ${info.fontName}${isKrutiDevLocal ? " — Kruti Dev detected! ✅" : ""})` : "";
      showStatus(`✅ ${info.text.length} अक्षर पढ़े गए${fontMsg}`, "success");
    } catch (error) {
      showStatus("❌ Text पढ़ने में त्रुटि। कृपया पुनः प्रयास करें।", "error");
      console.error("Read selection error:", error);
    }
    setIsLoading(false);
  }, [showStatus, isKrutiDev]);

  const handleReadDocument = useCallback(async () => {
    setIsLoading(true);
    try {
      const text = await getDocumentBody();
      if (!text.trim()) {
        showStatus("दस्तावेज़ खाली है।", "error");
        setIsLoading(false);
        return;
      }
      setSelectedText(text);
      setEditedText(text);
      setFontDetected("");
      setSpellingIssues([]);
      setShowSpellPanel(false);
      setGrammarIssues([]);
      setShowGrammarPanel(false);
      setShowTemplates(false);
      showStatus(`✅ पूरा दस्तावेज़ पढ़ा गया (${text.length} अक्षर)`, "success");
    } catch (error) {
      showStatus("❌ दस्तावेज़ पढ़ने में त्रुटि।", "error");
      console.error("Read document error:", error);
    }
    setIsLoading(false);
  }, [showStatus]);

  const handleReplace = useCallback(async () => {
    if (!editedText.trim()) {
      showStatus("बदलने के लिए कोई text नहीं है।", "error");
      return;
    }
    setIsLoading(true);
    try {
      await replaceSelectedText(editedText);
      showStatus("✅ Text सफलतापूर्वक बदल दिया गया!", "success");
    } catch (error) {
      showStatus("❌ Text बदलने में त्रुटि। क्या Word में text चयनित है?", "error");
      console.error("Replace error:", error);
    }
    setIsLoading(false);
  }, [editedText, showStatus]);

  const handleClear = useCallback(() => {
    setSelectedText("");
    setEditedText("");
    setFontDetected("");
    setSpellingIssues([]);
    setShowSpellPanel(false);
    setGrammarIssues([]);
    setShowGrammarPanel(false);
    setShowTemplates(false);
    showStatus("साफ़ किया गया। नया text चुनें।", "info");
  }, [showStatus]);

  const handleConvertToUnicode = useCallback(() => {
    if (!editedText.trim()) return;
    const converted = krutiDevToUnicode(editedText);
    setEditedText(converted);
    setIsKrutiDev(false);
    setSpellingIssues([]);
    setShowSpellPanel(false);
    setGrammarIssues([]);
    setShowGrammarPanel(false);
    showStatus("✅ Kruti Dev → Unicode में बदला गया", "success");
  }, [editedText, showStatus]);

  const handleConvertToKrutiDev = useCallback(() => {
    if (!editedText.trim()) return;
    const converted = unicodeToKrutiDev(editedText);
    setEditedText(converted);
    setIsKrutiDev(true);
    setSpellingIssues([]);
    setShowSpellPanel(false);
    setGrammarIssues([]);
    setShowGrammarPanel(false);
    showStatus("✅ Unicode → Kruti Dev में बदला गया", "success");
  }, [editedText, showStatus]);

  // --- Spell Checker Handlers ---
  const handleCheckSpelling = useCallback(() => {
    if (!editedText.trim()) {
      showStatus("जाँच के लिए कोई text उपलब्ध नहीं है।", "error");
      return;
    }

    if (isKrutiDev || isKrutiDevText(editedText)) {
      showStatus("⚠️ यह Kruti Dev text है। वर्तनी जाँच से पहले 'Kruti Dev → Unicode' दबाएँ।", "info");
      return;
    }

    const issues = checkHindiSpelling(editedText, ignoredWords);
    setSpellingIssues(issues);
    setShowSpellPanel(true);
    setShowGrammarPanel(false);

    if (issues.length === 0) {
      showStatus("✅ बहुत बढ़िया! कोई वर्तनी त्रुटि नहीं मिली।", "success");
    } else {
      showStatus(`⚠️ ${issues.length} वर्तनी त्रुटियाँ मिलीं। नीचे सुझाव देखें।`, "info");
    }
  }, [editedText, ignoredWords, isKrutiDev, showStatus]);

  const handleApplySuggestion = useCallback((issue: SpellingIssue, suggestion: string) => {
    const updated = editedText.slice(0, issue.start) + suggestion + editedText.slice(issue.end);
    setEditedText(updated);

    const rechecked = checkHindiSpelling(updated, ignoredWords);
    setSpellingIssues(rechecked);

    showStatus(`✅ "${issue.word}" को बदलकर "${suggestion}" किया गया`, "success");
  }, [editedText, ignoredWords, showStatus]);

  const handleIgnoreWord = useCallback((word: string) => {
    const updatedIgnored = new Set(ignoredWords);
    updatedIgnored.add(word);
    setIgnoredWords(updatedIgnored);

    const filtered = spellingIssues.filter(i => i.word !== word);
    setSpellingIssues(filtered);
    showStatus(`👁️ "${word}" को इस सत्र के लिए अनदेखा किया गया`, "info");
  }, [ignoredWords, spellingIssues, showStatus]);

  const handleAddWordToDictionary = useCallback((word: string) => {
    const success = addCustomWord(word);
    if (success) {
      const filtered = spellingIssues.filter(i => i.word !== word);
      setSpellingIssues(filtered);
      showStatus(`📖 "${word}" को आपके निजी शब्दकोश में जोड़ दिया गया`, "success");
    } else {
      showStatus(`ℹ️ "${word}" पहले से शब्दकोश में मौजूद है`, "info");
    }
  }, [spellingIssues, showStatus]);

  // --- Grammar Checker Handlers ---
  const handleCheckGrammar = useCallback(() => {
    if (!editedText.trim()) {
      showStatus("जाँच के लिए कोई text उपलब्ध नहीं है।", "error");
      return;
    }

    if (isKrutiDev || isKrutiDevText(editedText)) {
      showStatus("⚠️ यह Kruti Dev text है। व्याकरण जाँच से पहले 'Kruti Dev → Unicode' दबाएँ।", "info");
      return;
    }

    const issues = checkHindiGrammar(editedText, ignoredGrammarRuleIds);
    setGrammarIssues(issues);
    setShowGrammarPanel(true);
    setShowSpellPanel(false);

    if (issues.length === 0) {
      showStatus("✅ अति उत्तम! कोई व्याकरणिक या शैलीगत अशुद्धि नहीं मिली।", "success");
    } else {
      showStatus(`✍️ ${issues.length} व्याकरण एवं प्रशासनिक शैली सुझाव उपलब्ध हैं।`, "info");
    }
  }, [editedText, ignoredGrammarRuleIds, isKrutiDev, showStatus]);

  const handleApplyGrammarIssue = useCallback((issue: GrammarIssue) => {
    const updated = editedText.slice(0, issue.start) + issue.replacement + editedText.slice(issue.end);
    setEditedText(updated);

    const rechecked = checkHindiGrammar(updated, ignoredGrammarRuleIds);
    setGrammarIssues(rechecked);

    showStatus(`✅ "${issue.original}" को बदलकर "${issue.replacement}" किया गया`, "success");
  }, [editedText, ignoredGrammarRuleIds, showStatus]);

  const handleIgnoreGrammarIssue = useCallback((issueId: string) => {
    const updated = new Set(ignoredGrammarRuleIds);
    updated.add(issueId);
    setIgnoredGrammarRuleIds(updated);

    const filtered = grammarIssues.filter(i => i.id !== issueId);
    setGrammarIssues(filtered);
    showStatus("👁️ सुझाव अनदेखा किया गया", "info");
  }, [grammarIssues, ignoredGrammarRuleIds, showStatus]);

  // --- Document Tools Handlers ---
  const handleOpenDocTools = useCallback(async () => {
    setIsLoading(true);
    try {
      const paragraphs = await getDocumentParagraphs();
      const fullText = paragraphs.length > 0 ? paragraphs.map(p => p.text).join("\n") : editedText;
      
      const words = fullText.trim() ? fullText.trim().split(/\s+/).length : 0;
      const chars = fullText.length;
      const numParagraphs = paragraphs.length > 0 ? paragraphs.length : (fullText ? fullText.split(/\n+/).length : 0);
      const hasKD = isKrutiDevText(fullText) || paragraphs.some(p => p.fontName.toLowerCase().includes("kruti") || p.fontName.toLowerCase().includes("krdv"));

      setDocStats({
        paragraphs: numParagraphs,
        words,
        chars,
        hasKrutiDev: hasKD,
      });
      setShowDocTools(prev => !prev);
      showStatus("📑 दस्तावेज़ टूल्स खोले गए।", "info");
    } catch {
      setShowDocTools(prev => !prev);
    }
    setIsLoading(false);
  }, [editedText, showStatus]);

  const handleScanFullDocument = useCallback(async () => {
    setIsLoading(true);
    showStatus("⏳ पूरे दस्तावेज़ का विश्लेषण किया जा रहा है...", "info");
    try {
      const fullText = await getDocumentBody() || editedText;
      if (!fullText.trim()) {
        showStatus("दस्तावेज़ खाली है।", "error");
        setIsLoading(false);
        return;
      }

      setSelectedText(fullText);
      setEditedText(fullText);

      // Run both checks
      const spellResults = checkHindiSpelling(fullText, ignoredWords);
      const grammarResults = checkHindiGrammar(fullText, ignoredGrammarRuleIds);

      setSpellingIssues(spellResults);
      setGrammarIssues(grammarResults);

      if (spellResults.length > 0) {
        setShowSpellPanel(true);
      }
      if (grammarResults.length > 0) {
        setShowGrammarPanel(true);
      }

      showStatus(
        `✅ विश्लेषण पूर्ण! ${spellResults.length} वर्तनी त्रुटियाँ, ${grammarResults.length} व्याकरणिक सुझाव।`,
        spellResults.length === 0 && grammarResults.length === 0 ? "success" : "info"
      );
    } catch (error) {
      showStatus("❌ दस्तावेज़ स्कैन में त्रुटि।", "error");
      console.error(error);
    }
    setIsLoading(false);
  }, [editedText, ignoredWords, ignoredGrammarRuleIds, showStatus]);

  const handleConvertEntireDocToUnicode = useCallback(async () => {
    setIsLoading(true);
    showStatus("⏳ पूरे दस्तावेज़ को Unicode में बदला जा रहा है...", "info");
    try {
      const fullText = await getDocumentBody() || editedText;
      const converted = krutiDevToUnicode(fullText);

      await replaceDocumentBody(converted, "Mangal");
      setSelectedText(converted);
      setEditedText(converted);
      setIsKrutiDev(false);
      setSpellingIssues([]);
      setGrammarIssues([]);

      showStatus("✅ पूरा दस्तावेज़ Unicode में बदल दिया गया (फॉन्ट 'Mangal' सेट हुआ)!", "success");
    } catch (error) {
      showStatus("❌ दस्तावेज़ रूपांतरण में त्रुटि।", "error");
      console.error(error);
    }
    setIsLoading(false);
  }, [editedText, showStatus]);

  const handleConvertEntireDocToKrutiDev = useCallback(async () => {
    setIsLoading(true);
    showStatus("⏳ पूरे दस्तावेज़ को Kruti Dev में बदला जा रहा है...", "info");
    try {
      const fullText = await getDocumentBody() || editedText;
      const converted = unicodeToKrutiDev(fullText);

      await replaceDocumentBody(converted, "Kruti Dev 010");
      setSelectedText(converted);
      setEditedText(converted);
      setIsKrutiDev(true);
      setSpellingIssues([]);
      setGrammarIssues([]);

      showStatus("✅ पूरा दस्तावेज़ Kruti Dev 010 में बदल दिया गया!", "success");
    } catch (error) {
      showStatus("❌ दस्तावेज़ रूपांतरण में त्रुटि।", "error");
      console.error(error);
    }
    setIsLoading(false);
  }, [editedText, showStatus]);

  const handleFindInWord = useCallback(async (query: string) => {
    if (!query.trim()) return;
    setIsLoading(true);
    try {
      const found = await searchAndSelectInDocument(query);
      if (found) {
        showStatus(`🎯 Word दस्तावेज़ में "${query}" खोजा एवं चयनित किया गया!`, "success");
      } else {
        showStatus(`⚠️ दस्तावेज़ में "${query}" नहीं मिला।`, "error");
      }
    } catch (error) {
      showStatus("खोजने में त्रुटि।", "error");
      console.error(error);
    }
    setIsLoading(false);
  }, [showStatus]);

  // --- Template Handlers ---
  const handleLoadTemplateIntoEditor = useCallback((text: string) => {
    setEditedText(text);
    setSelectedText(text);
    setShowTemplates(false);
    setSpellingIssues([]);
    setShowSpellPanel(false);
    setGrammarIssues([]);
    setShowGrammarPanel(false);
    showStatus("✅ पत्र प्रारूप संपादक (Editor) में लोड कर दिया गया!", "success");
  }, [showStatus]);

  const handleInsertTemplateIntoWord = useCallback(async (text: string, fontName: string) => {
    setIsLoading(true);
    showStatus("⏳ Word दस्तावेज़ में पत्र डाला जा रहा है...", "info");
    try {
      const selInfo = await getSelectionInfo().catch(() => ({ text: "", fontName: "" }));
      if (selInfo.text.trim()) {
        await replaceSelectedText(text, fontName);
      } else {
        await replaceDocumentBody(text, fontName);
      }
      setSelectedText(text);
      setEditedText(text);
      setFontDetected(fontName);
      setIsKrutiDev(fontName.toLowerCase().includes("kruti") || fontName.toLowerCase().includes("krdv"));
      setShowTemplates(false);
      showStatus(`✅ पत्र Word दस्तावेज़ में सफलतापूर्वक डाला गया (${fontName})!`, "success");
    } catch (error) {
      showStatus("❌ Word में पत्र डालने में त्रुटि।", "error");
      console.error("Insert template error:", error);
    }
    setIsLoading(false);
  }, [showStatus]);

  return (
    <div className={`app-container font-size-${fontSizeScale}`}>
      <Header
        fontSizeScale={fontSizeScale}
        onChangeFontSize={handleFontSizeChange}
        onOpenHelp={() => setShowHelp(true)}
      />
      <ActionBar
        onReadSelection={handleReadSelection}
        onReadDocument={handleReadDocument}
        onOpenDocTools={() => {
          setShowDocTools(prev => !prev);
          setShowTemplates(false);
          setShowSpellPanel(false);
          setShowGrammarPanel(false);
        }}
        onOpenTemplates={() => {
          setShowTemplates(prev => !prev);
          setShowDocTools(false);
          setShowSpellPanel(false);
          setShowGrammarPanel(false);
        }}
        onReplace={handleReplace}
        onClear={handleClear}
        onCheckSpelling={handleCheckSpelling}
        onCheckGrammar={handleCheckGrammar}
        isLoading={isLoading}
        hasText={!!editedText.trim()}
        spellingCount={spellingIssues.length}
        grammarCount={grammarIssues.length}
      />
      <ConversionBar
        onConvertToUnicode={handleConvertToUnicode}
        onConvertToKrutiDev={handleConvertToKrutiDev}
        isLoading={isLoading}
        hasText={!!editedText.trim()}
        isKrutiDev={isKrutiDev}
      />
      {fontDetected && (
        <div className={`font-badge ${fontDetected.toLowerCase().includes('kruti') ? 'font-badge-krutidev' : 'font-badge-other'}`}>
          Font: {fontDetected}
          {fontDetected.toLowerCase().includes('kruti') && " — Kruti Dev ✅"}
        </div>
      )}
      {showTemplates && (
        <TemplatesPanel
          onLoadIntoEditor={handleLoadTemplateIntoEditor}
          onInsertIntoWord={handleInsertTemplateIntoWord}
          onClose={() => setShowTemplates(false)}
        />
      )}
      {showDocTools && (
        <DocumentToolsPanel
          onScanFullDocument={handleScanFullDocument}
          onConvertEntireDocToUnicode={handleConvertEntireDocToUnicode}
          onConvertEntireDocToKrutiDev={handleConvertEntireDocToKrutiDev}
          onFindInWord={handleFindInWord}
          isLoading={isLoading}
          docStats={docStats}
          onClose={() => setShowDocTools(false)}
        />
      )}
      {showSpellPanel && (
        <SpellCheckPanel
          issues={spellingIssues}
          onApplySuggestion={handleApplySuggestion}
          onIgnoreWord={handleIgnoreWord}
          onAddWordToDictionary={handleAddWordToDictionary}
          onClose={() => setShowSpellPanel(false)}
        />
      )}
      {showGrammarPanel && (
        <GrammarPanel
          issues={grammarIssues}
          onApplyIssue={handleApplyGrammarIssue}
          onIgnoreIssue={handleIgnoreGrammarIssue}
          onClose={() => setShowGrammarPanel(false)}
        />
      )}
      <TextDisplay
        originalText={selectedText}
        editedText={editedText}
        isKrutiDev={isKrutiDev}
        onEditedTextChange={(text) => {
          setEditedText(text);
          if (showSpellPanel) {
            setSpellingIssues([]);
            setShowSpellPanel(false);
          }
          if (showGrammarPanel) {
            setGrammarIssues([]);
            setShowGrammarPanel(false);
          }
        }}
      />
      <StatusBar message={status} type={statusType} />
      <HelpModal isOpen={showHelp} onClose={() => setShowHelp(false)} />
    </div>
  );
};
