import React, { useState } from "react";

interface TextDisplayProps {
  originalText: string;
  editedText: string;
  onEditedTextChange: (text: string) => void;
  isKrutiDev?: boolean;
}

export const TextDisplay: React.FC<TextDisplayProps> = ({
  originalText,
  editedText,
  onEditedTextChange,
  isKrutiDev = false,
}) => {
  const [renderInKrutiDev, setRenderInKrutiDev] = useState<boolean>(true);

  if (!originalText && !editedText) {
    return (
      <div className="text-display-empty">
        <div className="empty-icon">📝</div>
        <p className="empty-text">
          Word में text चुनें और<br />
          <strong>'चयन पढ़ें'</strong> बटन दबाएँ
        </p>
      </div>
    );
  }

  const applyKDClass = isKrutiDev && renderInKrutiDev;

  return (
    <div className="text-display">
      <div className="text-display-header">
        <label className="text-label" htmlFor="text-editor">
          Text (संपादित करें और 'बदलें' दबाएँ):
        </label>
        {isKrutiDev && (
          <button
            type="button"
            className="kd-view-toggle-btn"
            onClick={() => setRenderInKrutiDev(prev => !prev)}
            title="Kruti Dev और Raw ASCII के बीच दृश्य बदलें"
          >
            {renderInKrutiDev ? "🔤 Kruti Dev फ़ॉन्ट दृश्य ऑन" : "🔡 Raw Text दृश्य"}
          </button>
        )}
      </div>
      <textarea
        id="text-editor"
        className={`text-editor ${applyKDClass ? "krutidev-text krutidev-editor" : ""}`}
        value={editedText}
        onChange={(e) => onEditedTextChange(e.target.value)}
        placeholder="यहाँ text दिखाई देगा..."
        rows={10}
        dir="auto"
      />
      {originalText !== editedText && (
        <div className="text-modified-badge">
          ⚠️ Text में बदलाव किया गया है
        </div>
      )}
    </div>
  );
};
