/**
 * Word API Wrapper
 *
 * Encapsulates all Office.js Word document interactions.
 * All functions use the Word.run() pattern for proper context management.
 * Includes graceful browser fallback for local testing.
 */

/// <reference types="office-js" />

function isOfficeWordAvailable(): boolean {
  return typeof Office !== "undefined" && typeof Word !== "undefined" && typeof Word.run === "function";
}

/**
 * Read the currently selected text in Word.
 */
export async function getSelectedText(): Promise<string> {
  if (!isOfficeWordAvailable()) {
    return "";
  }

  return Word.run(async (context) => {
    const selection = context.document.getSelection();
    selection.load("text");
    await context.sync();
    return selection.text || "";
  });
}

/**
 * Get information about the current selection (text + font name).
 */
export async function getSelectionInfo(): Promise<{ text: string; fontName: string }> {
  if (!isOfficeWordAvailable()) {
    return { text: "", fontName: "" };
  }

  return Word.run(async (context) => {
    const selection = context.document.getSelection();
    selection.load("text");
    selection.font.load("name");
    await context.sync();
    return {
      text: selection.text || "",
      fontName: selection.font.name || "",
    };
  });
}

/**
 * Replace the currently selected text in Word with new text and optional font change.
 */
export async function replaceSelectedText(newText: string, targetFontName?: string): Promise<void> {
  if (!isOfficeWordAvailable()) {
    return;
  }

  await Word.run(async (context) => {
    const selection = context.document.getSelection();
    const range = selection.insertText(newText, Word.InsertLocation.replace);
    if (targetFontName) {
      range.font.name = targetFontName;
    }
    await context.sync();
  });
}

/**
 * Read the entire document body text.
 */
export async function getDocumentBody(): Promise<string> {
  if (!isOfficeWordAvailable()) {
    return "";
  }

  return Word.run(async (context) => {
    const body = context.document.body;
    body.load("text");
    await context.sync();
    return body.text || "";
  });
}

/**
 * Replace entire document body text with optional font change.
 */
export async function replaceDocumentBody(newText: string, targetFontName?: string): Promise<void> {
  if (!isOfficeWordAvailable()) {
    return;
  }

  await Word.run(async (context) => {
    const body = context.document.body;
    const range = body.insertText(newText, Word.InsertLocation.replace);
    if (targetFontName) {
      range.font.name = targetFontName;
    }
    await context.sync();
  });
}

/**
 * Search for a query string in Word document and select the first match.
 * Automatically scrolls Word viewport to the match so the user sees it in their document.
 */
export async function searchAndSelectInDocument(query: string): Promise<boolean> {
  if (!isOfficeWordAvailable() || !query.trim()) {
    return false;
  }

  return Word.run(async (context) => {
    const results = context.document.body.search(query, { matchCase: true, matchWholeWord: false });
    results.load("items");
    await context.sync();

    if (results.items.length > 0) {
      results.items[0].select();
      await context.sync();
      return true;
    }

    return false;
  });
}

/**
 * Batch replace all occurrences of a search string in the entire Word document.
 * Returns the number of replacements made.
 */
export async function replaceAllInDocument(
  findText: string,
  replaceText: string,
  targetFontName?: string
): Promise<number> {
  if (!isOfficeWordAvailable() || !findText.trim()) {
    return 0;
  }

  return Word.run(async (context) => {
    const results = context.document.body.search(findText, { matchCase: true, matchWholeWord: false });
    results.load("items");
    await context.sync();

    const count = results.items.length;
    for (let i = 0; i < count; i++) {
      const item = results.items[i];
      const range = item.insertText(replaceText, Word.InsertLocation.replace);
      if (targetFontName) {
        range.font.name = targetFontName;
      }
    }

    await context.sync();
    return count;
  });
}

/**
 * Get paragraph breakdown of the document with text and font names.
 */
export async function getDocumentParagraphs(): Promise<{ text: string; fontName: string }[]> {
  if (!isOfficeWordAvailable()) {
    return [];
  }

  return Word.run(async (context) => {
    const paragraphs = context.document.body.paragraphs;
    paragraphs.load("items");
    await context.sync();

    for (const p of paragraphs.items) {
      p.load("text");
      p.font.load("name");
    }
    await context.sync();

    return paragraphs.items.map((p) => ({
      text: p.text || "",
      fontName: p.font.name || "",
    }));
  });
}
