/**
 * Personal Dictionary Service
 * Stores user-added words persistently in localStorage.
 */

const STORAGE_KEY = "hindi_assistant_personal_dict";

export function getCustomWords(): string[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function addCustomWord(word: string): boolean {
  const trimmed = word.trim();
  if (!trimmed) return false;

  const current = getCustomWords();
  if (current.includes(trimmed)) return false;

  const updated = [...current, trimmed];
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    return true;
  } catch {
    return false;
  }
}

export function removeCustomWord(word: string): boolean {
  const trimmed = word.trim();
  const current = getCustomWords();
  const updated = current.filter(w => w !== trimmed);
  if (updated.length === current.length) return false;

  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    return true;
  } catch {
    return false;
  }
}

export function clearPersonalDictionary(): void {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    // Ignore storage errors
  }
}
