import React from "react";
import { GrammarIssue } from "../../grammar";

interface GrammarPanelProps {
  issues: GrammarIssue[];
  onApplyIssue: (issue: GrammarIssue) => void;
  onIgnoreIssue: (issueId: string) => void;
  onClose: () => void;
}

export const GrammarPanel: React.FC<GrammarPanelProps> = ({
  issues,
  onApplyIssue,
  onIgnoreIssue,
  onClose,
}) => {
  if (issues.length === 0) {
    return (
      <div className="grammar-panel grammar-panel-clean">
        <div className="grammar-clean-content">
          <span className="clean-icon">📜</span>
          <div>
            <h3 className="clean-title">व्याकरण एवं प्रशासनिक शैली उत्तम है!</h3>
            <p className="clean-subtitle">दस्तावेज़ में कोई व्याकरणिक या शैलीगत अशुद्धि नहीं पाई गई।</p>
          </div>
        </div>
        <button className="spellcheck-close-btn" onClick={onClose} title="बंद करें">
          ✕
        </button>
      </div>
    );
  }

  return (
    <div className="grammar-panel">
      <div className="grammar-header">
        <div className="grammar-header-title">
          <span className="grammar-icon">✍️</span>
          <span className="grammar-title">व्याकरण एवं प्रशासनिक शैली सुधार</span>
          <span className="grammar-badge">{issues.length} सुझाव</span>
        </div>
        <button className="spellcheck-close-btn" onClick={onClose} title="बंद करें">
          ✕
        </button>
      </div>

      <div className="grammar-list">
        {issues.map((issue) => (
          <div key={issue.id} className={`grammar-card grammar-card-${issue.category}`}>
            <div className="grammar-card-header">
              <span className={`category-tag category-tag-${issue.category}`}>
                {issue.categoryLabel}
              </span>
              <span className="grammar-rule-title">{issue.title}</span>
            </div>

            <div className="grammar-diff-box">
              <div className="diff-item diff-original">
                <span className="diff-label">मूल:</span>
                <span className="diff-text original-text">{issue.original}</span>
              </div>
              <span className="diff-arrow">➔</span>
              <div className="diff-item diff-replacement">
                <span className="diff-label">मानक:</span>
                <span className="diff-text replacement-text">{issue.replacement}</span>
              </div>
            </div>

            <p className="grammar-explanation">
              💡 {issue.explanation}
            </p>

            <div className="grammar-card-actions">
              <button
                className="grammar-apply-btn"
                onClick={() => onApplyIssue(issue)}
                title={`"${issue.original}" को "${issue.replacement}" से बदलें`}
              >
                ✓ बदलें
              </button>
              <button
                className="action-link-btn"
                onClick={() => onIgnoreIssue(issue.id)}
                title="इस सुझाव को अनदेखा करें"
              >
                👁️ अनदेखा करें
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
