/**
 * Hindi-Aware Phonetic Edit Distance
 * 
 * Calculates distance between two Hindi words with weighted penalties
 * for common phonological and typing confusions in Devanagari.
 */

const CONFUSION_PAIRS: [string, string, number][] = [
  // Matra i / ee
  ["ि", "ी", 0.3],
  // Matra u / oo
  ["ु", "ू", 0.3],
  // Independent vowels i / ee, u / oo
  ["इ", "ई", 0.4],
  ["उ", "ऊ", 0.4],
  ["ए", "ऐ", 0.4],
  ["ओ", "औ", 0.4],
  // Sibilants
  ["श", "ष", 0.3],
  ["श", "स", 0.4],
  ["ष", "स", 0.4],
  // Ba / Va
  ["ब", "व", 0.4],
  // Nasals
  ["ं", "ँ", 0.2],
  ["ण", "न", 0.4],
  // Ksh / Chh
  ["क्ष", "छ", 0.5],
  // Nukta pairs
  ["क", "क़", 0.2],
  ["ख", "ख़", 0.2],
  ["ग", "ग़", 0.2],
  ["ज", "ज़", 0.2],
  ["फ", "फ़", 0.2],
  ["ड", "ड़", 0.2],
  ["ढ", "ढ़", 0.2],
];

function getSubstitutionCost(a: string, b: string): number {
  if (a === b) return 0;

  for (const [c1, c2, cost] of CONFUSION_PAIRS) {
    if ((a === c1 && b === c2) || (a === c2 && b === c1)) {
      return cost;
    }
  }

  return 1.0;
}

export function hindiLevenshteinDistance(s1: string, s2: string): number {
  if (s1 === s2) return 0;
  if (s1.length === 0) return s2.length;
  if (s2.length === 0) return s1.length;

  const m = s1.length;
  const n = s2.length;

  // Optimized two-row DP
  let prev = new Float32Array(n + 1);
  let curr = new Float32Array(n + 1);

  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const char1 = s1[i - 1];

    for (let j = 1; j <= n; j++) {
      const char2 = s2[j - 1];
      const subCost = getSubstitutionCost(char1, char2);

      const costInsert = curr[j - 1] + 1;
      const costDelete = prev[j] + 1;
      const costSub = prev[j - 1] + subCost;

      curr[j] = Math.min(costInsert, costDelete, costSub);
    }

    // Swap rows
    const temp = prev;
    prev = curr;
    curr = temp;
  }

  return prev[n];
}
