import { isKnownWord, getAllKnownWords } from "../dictionary";
import { tokenizeHindiText, getWordContext } from "./tokenizer";
import { hindiLevenshteinDistance } from "./levenshtein";
import { SpellingIssue } from "./types";

/**
 * Generates ranked suggestions for an unknown Hindi word.
 */
export function getSuggestions(word: string, maxSuggestions: number = 4): string[] {
  const allWords = getAllKnownWords();
  const wordLen = word.length;

  const scoredCandidates: { word: string; dist: number }[] = [];

  for (const candidate of allWords) {
    // Length pruning: skip if length difference is too large
    if (Math.abs(candidate.length - wordLen) > 3) {
      continue;
    }

    const dist = hindiLevenshteinDistance(word, candidate);

    // Only consider reasonably close matches
    if (dist <= 2.6) {
      scoredCandidates.push({ word: candidate, dist });
    }
  }

  // Sort by lowest distance
  scoredCandidates.sort((a, b) => a.dist - b.dist);

  // Return top unique suggestions
  const seen = new Set<string>();
  const results: string[] = [];

  for (const c of scoredCandidates) {
    if (!seen.has(c.word) && c.word !== word) {
      seen.add(c.word);
      results.push(c.word);
      if (results.length >= maxSuggestions) {
        break;
      }
    }
  }

  return results;
}

/**
 * Scans text and identifies spelling issues with suggestions.
 */
export function checkHindiSpelling(
  text: string,
  ignoredWords?: Set<string>,
  customWords?: Set<string>
): SpellingIssue[] {
  if (!text || !text.trim()) {
    return [];
  }

  const tokens = tokenizeHindiText(text);
  const issues: SpellingIssue[] = [];

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    const word = token.word;

    // Skip if in ignore set
    if (ignoredWords && ignoredWords.has(word)) {
      continue;
    }

    // Skip if known word
    if (isKnownWord(word, customWords)) {
      continue;
    }

    // Generate suggestions
    const suggestions = getSuggestions(word);
    const context = getWordContext(text, token.start, token.end);

    issues.push({
      id: `spell-${token.start}-${token.end}-${word}`,
      word,
      start: token.start,
      end: token.end,
      context,
      suggestions,
    });
  }

  return issues;
}
