export type GrammarRuleCategory = 
  | 'redundancy'       // अनावश्यक शब्द / पुनरुक्ति (e.g. कृपया करके -> कृपया)
  | 'administrative'   // प्रशासनिक एवं औपचारिक शब्दावली (e.g. उपरोक्त -> उपर्युक्त)
  | 'agreement'        // लिंग / वचन / पुरुष अन्विति (e.g. आप करता है -> आप करते हैं)
  | 'honorific';       // आदरार्थक प्रयोग (e.g. पिताजी आया -> पिताजी आए)

export interface GrammarIssue {
  id: string;
  category: GrammarRuleCategory;
  categoryLabel: string;
  title: string;
  explanation: string;
  original: string;
  replacement: string;
  start: number;
  end: number;
  context: string;
}

export interface GrammarRule {
  id: string;
  category: GrammarRuleCategory;
  categoryLabel: string;
  title: string;
  explanation: string;
  pattern: RegExp;
  replace: (match: string, ...args: any[]) => string;
}

/**
 * Creates a regex with Devanagari word boundaries.
 * Standard \b does not work for Devanagari Unicode characters in JS.
 */
export function createRulePattern(body: string, flags: string = "g"): RegExp {
  return new RegExp(`(?<=^|[^\\u0900-\\u097F])${body}(?=[^\\u0900-\\u097F]|$)`, flags);
}
