import React from "react";

interface ConversionBarProps {
  onConvertToUnicode: () => void;
  onConvertToKrutiDev: () => void;
  isLoading: boolean;
  hasText: boolean;
  isKrutiDev: boolean;
}

export const ConversionBar: React.FC<ConversionBarProps> = ({
  onConvertToUnicode,
  onConvertToKrutiDev,
  isLoading,
  hasText,
  isKrutiDev,
}) => {
  return (
    <div className="conversion-bar">
      <div className="conversion-header">
        <span className="conversion-title">🔄 रूपांतरण (Conversion)</span>
      </div>
      <div className="action-row">
        <button
          className={`action-btn ${isKrutiDev ? 'action-btn-primary' : 'action-btn-secondary'}`}
          onClick={onConvertToUnicode}
          disabled={isLoading || !hasText}
          title="Kruti Dev text को Unicode Hindi में बदलें"
        >
          <span className="action-btn-icon">🔤</span>
          <span className="action-btn-label">Kruti Dev → Unicode</span>
        </button>
        <button
          className="action-btn action-btn-secondary"
          onClick={onConvertToKrutiDev}
          disabled={isLoading || !hasText}
          title="Unicode Hindi को Kruti Dev में बदलें"
        >
          <span className="action-btn-icon">🔡</span>
          <span className="action-btn-label">Unicode → Kruti Dev</span>
        </button>
      </div>
      {isKrutiDev && hasText && (
        <div className="conversion-hint">
          💡 Kruti Dev text detected! "Kruti Dev → Unicode" दबाएँ
        </div>
      )}
    </div>
  );
};
